INSERT INTO source (id, title, celex, url, section, retrieved) VALUES
  ('espr', 'Regulation (EU) 2024/1781 (Ecodesign for Sustainable Products Regulation)', '32024R1781', 'https://eur-lex.europa.eu/legal-content/EN/TXT/HTML/?uri=OJ:L_202401781', 'Annex I - Product parameters', '2026-11-03');
INSERT INTO tree (id, side, title, subtitle, root_id) VALUES
  ('espr-annex-i', 'right', 'Data category', 'ESPR (EU) 2024/1781, Annex I product parameters', 'root');
INSERT INTO node (tree_id, id, parent_id, position, name, meta, description, source_id, source_ref) VALUES
  ('espr-annex-i', 'root', NULL, '0', 'ESPR Annex I', NULL, 'The following parameters shall, as appropriate, and where necessary supplemented by others, be used, individually or in combination, as a basis for improving the product aspects:', 'espr', 'Annex I'),
  ('espr-annex-i', 'espr-a', 'root', '0', 'Durability and reliability', 'Annex I(a)', 'durability and reliability of the product or its components as expressed through the product’s guaranteed lifetime, technical lifetime, mean time between failures, indication of real use information on the product, resistance to stresses or ageing mechanisms;', 'espr', 'Annex I(a)'),
  ('espr-annex-i', 'espr-a-1', 'espr-a', '0', 'Guaranteed lifetime', NULL, NULL, 'espr', 'Annex I(a)'),
  ('espr-annex-i', 'espr-a-2', 'espr-a', '1', 'Technical lifetime', NULL, NULL, 'espr', 'Annex I(a)'),
  ('espr-annex-i', 'espr-a-3', 'espr-a', '2', 'Mean time between failures', NULL, NULL, 'espr', 'Annex I(a)'),
  ('espr-annex-i', 'espr-a-4', 'espr-a', '3', 'Indication of real use information on the product', NULL, NULL, 'espr', 'Annex I(a)'),
  ('espr-annex-i', 'espr-a-5', 'espr-a', '4', 'Resistance to stresses or ageing mechanisms', NULL, NULL, 'espr', 'Annex I(a)'),
  ('espr-annex-i', 'espr-b', 'root', '1', 'Ease of repair and maintenance', 'Annex I(b)', 'ease of repair and maintenance, as expressed through characteristics, availability, delivery time and affordability of spare parts, modularity, compatibility with commonly available tools and spare parts, availability of repair and maintenance instructions, number of materials and components used, use of standard components, use of component and material coding standards for the identification of components and materials, number and complexity of processes and whether specialised tools are needed, ease of non-destructive disassembly and re-assembly, conditions for access to product data, conditions for access to or use of hardware and software needed;', 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-1', 'espr-b', '0', 'Characteristics, availability, delivery time and affordability of spare parts', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-2', 'espr-b', '1', 'Modularity', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-3', 'espr-b', '2', 'Compatibility with commonly available tools and spare parts', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-4', 'espr-b', '3', 'Availability of repair and maintenance instructions', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-5', 'espr-b', '4', 'Number of materials and components used', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-6', 'espr-b', '5', 'Use of standard components', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-7', 'espr-b', '6', 'Use of component and material coding standards for the identification of components and materials', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-8', 'espr-b', '7', 'Number and complexity of processes and whether specialised tools are needed', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-9', 'espr-b', '8', 'Ease of non-destructive disassembly and re-assembly', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-10', 'espr-b', '9', 'Conditions for access to product data', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-b-11', 'espr-b', '10', 'Conditions for access to or use of hardware and software needed', NULL, NULL, 'espr', 'Annex I(b)'),
  ('espr-annex-i', 'espr-c', 'root', '2', 'Ease of upgrading, reuse, remanufacturing and refurbishment', 'Annex I(c)', 'ease of upgrading, reuse, remanufacturing and refurbishment as expressed through number of materials and components used, use of standard components, use of component and material coding standards for the identification of components and materials, number and complexity of processes and tools needed, ease of non-destructive disassembly and re-assembly, conditions for access to product data, conditions for access to or use of hardware and software needed, conditions of access to test protocols or not commonly available testing equipment, availability of guarantees specific to remanufactured or refurbished products, conditions for access to or use of technologies protected by intellectual property rights, modularity;', 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-1', 'espr-c', '0', 'Number of materials and components used', NULL, NULL, 'espr', 'Annex I(c)'),
