  ('espr-annex-i', 'espr-c-3', 'espr-c', '2', 'Use of component and material coding standards for the identification of components and materials', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-4', 'espr-c', '3', 'Number and complexity of processes and tools needed', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-5', 'espr-c', '4', 'Ease of non-destructive disassembly and re-assembly', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-6', 'espr-c', '5', 'Conditions for access to product data', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-7', 'espr-c', '6', 'Conditions for access to or use of hardware and software needed', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-8', 'espr-c', '7', 'Conditions of access to test protocols or not commonly available testing equipment', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-9', 'espr-c', '8', 'Availability of guarantees specific to remanufactured or refurbished products', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-10', 'espr-c', '9', 'Conditions for access to or use of technologies protected by intellectual property rights', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-c-11', 'espr-c', '10', 'Modularity', NULL, NULL, 'espr', 'Annex I(c)'),
  ('espr-annex-i', 'espr-d', 'root', '3', 'Design for recycling, ease and quality of recycling', 'Annex I(d)', 'design for recycling, ease and quality of recycling as expressed through use of easily recyclable materials, safe, easy and non-destructive access to recyclable components and materials or components and materials containing hazardous substances and material composition and homogeneity, possibility for high-purity sorting, number of materials and components used, use of standard components, use of component and material coding standards for the identification of components and materials, number and complexity of processes and tools needed, ease of non-destructive disassembly and re-assembly, conditions for access to product data, conditions for access to or use of hardware and software needed;', 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-1', 'espr-d', '0', 'Use of easily recyclable materials', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-2', 'espr-d', '1', 'Safe, easy and non-destructive access to recyclable components and materials or components and materials containing hazardous substances', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-3', 'espr-d', '2', 'Material composition and homogeneity', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-4', 'espr-d', '3', 'Possibility for high-purity sorting', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-5', 'espr-d', '4', 'Number of materials and components used', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-6', 'espr-d', '5', 'Use of standard components', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-7', 'espr-d', '6', 'Use of component and material coding standards for the identification of components and materials', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-8', 'espr-d', '7', 'Number and complexity of processes and tools needed', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-9', 'espr-d', '8', 'Ease of non-destructive disassembly and re-assembly', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-10', 'espr-d', '9', 'Conditions for access to product data', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-d-11', 'espr-d', '10', 'Conditions for access to or use of hardware and software needed', NULL, NULL, 'espr', 'Annex I(d)'),
  ('espr-annex-i', 'espr-e', 'root', '4', 'Avoidance of technical solutions detrimental to circularity', 'Annex I(e)', 'avoidance of technical solutions detrimental to reuse, upgrading, repair, maintenance, refurbishment, remanufacturing and recycling of products and components;', 'espr', 'Annex I(e)'),
  ('espr-annex-i', 'espr-f', 'root', '5', 'Use of substances, including substances of concern', 'Annex I(f)', 'use of substances, and in particular the use of substances of concern, on their own, as constituents of substances or in mixtures, during the production process of products, or leading to their presence in products, including once those products become waste, and their impacts on human health and the environment;', 'espr', 'Annex I(f)'),
  ('espr-annex-i', 'espr-g', 'root', '6', 'Use or consumption of energy, water and other resources', 'Annex I(g)', 'use or consumption of energy, water and other resources in one or more life cycle stages of the product, including the effect of physical factors or software and firmware updates on product efficiency and including the impact on deforestation;', 'espr', 'Annex I(g)'),
  ('espr-annex-i', 'espr-h', 'root', '7', 'Recycled content and recovery of materials, including critical raw materials', 'Annex I(h)', 'use or content of recycled materials and recovery of materials, including critical raw materials;', 'espr', 'Annex I(h)'),
  ('espr-annex-i', 'espr-i', 'root', '8', 'Sustainable renewable materials', 'Annex I(i)', 'use or content of sustainable renewable materials;', 'espr', 'Annex I(i)'),
  ('espr-annex-i', 'espr-j', 'root', '9', 'Weight and volume of product and packaging', 'Annex I(j)', 'weight and volume of the product and its packaging, and the product-to-packaging ratio;', 'espr', 'Annex I(j)'),
  ('espr-annex-i', 'espr-k', 'root', '10', 'Incorporation of used components', 'Annex I(k)', 'incorporation of used components;', 'espr', 'Annex I(k)'),
  ('espr-annex-i', 'espr-l', 'root', '11', 'Consumables needed for proper use and maintenance', 'Annex I(l)', 'quantity, characteristics and availability of consumables needed for proper use and maintenance as expressed, inter alia, through yield, technical lifetime, ability to reuse, repair, and remanufacture, mass-resource efficiency, and interoperability;', 'espr', 'Annex I(l)'),
  ('espr-annex-i', 'espr-l-1', 'espr-l', '0', 'Yield', NULL, NULL, 'espr', 'Annex I(l)'),
  ('espr-annex-i', 'espr-l-2', 'espr-l', '1', 'Technical lifetime', NULL, NULL, 'espr', 'Annex I(l)'),
  ('espr-annex-i', 'espr-l-3', 'espr-l', '2', 'Ability to reuse, repair, and remanufacture', NULL, NULL, 'espr', 'Annex I(l)'),
  ('espr-annex-i', 'espr-l-4', 'espr-l', '3', 'Mass-resource efficiency', NULL, NULL, 'espr', 'Annex I(l)'),
  ('espr-annex-i', 'espr-l-5', 'espr-l', '4', 'Interoperability', NULL, NULL, 'espr', 'Annex I(l)'),
  ('espr-annex-i', 'espr-m', 'root', '12', 'Environmental footprint', 'Annex I(m)', 'the environmental footprint of the product, expressed as a quantification, in accordance with the applicable delegated act, of a product’s life cycle environmental impacts, whether in relation to one or more environmental impact categories or an aggregated set of impact categories;', 'espr', 'Annex I(m)'),
  ('espr-annex-i', 'espr-n', 'root', '13', 'Carbon footprint', 'Annex I(n)', 'the carbon footprint of the product;', 'espr', 'Annex I(n)'),
  ('espr-annex-i', 'espr-o', 'root', '14', 'Material footprint', 'Annex I(o)', 'the material footprint of the product;', 'espr', 'Annex I(o)'),
  ('espr-annex-i', 'espr-p', 'root', '15', 'Microplastic and nanoplastic release', 'Annex I(p)', 'microplastic and nanoplastic release as expressed through the release during relevant product life cycle stages, including manufacturing, transport, use and end-of-life stages;', 'espr', 'Annex I(p)'),
  ('espr-annex-i', 'espr-q', 'root', '16', 'Emissions to air, water or soil', 'Annex I(q)', 'emissions to air, water or soil released in one or more lifecycle stages of the product as expressed through quantities and nature of emissions, including noise;', 'espr', 'Annex I(q)'),
  ('espr-annex-i', 'espr-q-1', 'espr-q', '0', 'Quantities and nature of emissions', NULL, NULL, 'espr', 'Annex I(q)'),
  ('espr-annex-i', 'espr-q-2', 'espr-q', '1', 'Noise', NULL, NULL, 'espr', 'Annex I(q)'),
  ('espr-annex-i', 'espr-r', 'root', '17', 'Waste generated, including hazardous waste', 'Annex I(r)', 'amounts of waste generated, including plastic waste and packaging waste and their ease of reuse, and amounts of hazardous waste generated;', 'espr', 'Annex I(r)'),
  ('espr-annex-i', 'espr-s', 'root', '18', 'Functional performance and conditions for use', 'Annex I(s)', 'functional performance and conditions for use, including as expressed through the ability to perform its intended use, precautions for use, skills required and compatibility with other products or systems;', 'espr', 'Annex I(s)'),
  ('espr-annex-i', 'espr-s-1', 'espr-s', '0', 'Ability to perform its intended use', NULL, NULL, 'espr', 'Annex I(s)'),
  ('espr-annex-i', 'espr-s-2', 'espr-s', '1', 'Precautions for use', NULL, NULL, 'espr', 'Annex I(s)'),
  ('espr-annex-i', 'espr-s-3', 'espr-s', '2', 'Skills required', NULL, NULL, 'espr', 'Annex I(s)'),
  ('espr-annex-i', 'espr-s-4', 'espr-s', '3', 'Compatibility with other products or systems', NULL, NULL, 'espr', 'Annex I(s)'),
  ('espr-annex-i', 'espr-t', 'root', '19', 'Lightweight design', 'Annex I(t)', 'lightweight design as expressed through reduction of material consumption, load- and stress-optimisation of structures, integration of functions within the material or into a single product component, use of lower density or high-strength materials and hybrid materials, with regard to material savings, recycling and other circularity aspects, and waste reduction.', 'espr', 'Annex I(t)'),
  ('espr-annex-i', 'espr-t-1', 'espr-t', '0', 'Reduction of material consumption', NULL, NULL, 'espr', 'Annex I(t)'),
  ('espr-annex-i', 'espr-t-2', 'espr-t', '1', 'Load- and stress-optimisation of structures', NULL, NULL, 'espr', 'Annex I(t)'),
  ('espr-annex-i', 'espr-t-3', 'espr-t', '2', 'Integration of functions within the material or into a single product component', NULL, NULL, 'espr', 'Annex I(t)'),
  ('espr-annex-i', 'espr-t-4', 'espr-t', '3', 'Use of lower density or high-strength materials and hybrid materials', NULL, NULL, 'espr', 'Annex I(t)');
